import delhi from "../data/climate/delhi.json";
import jaipur from "../data/climate/jaipur.json";
import ahmedabad from "../data/climate/ahmedabad.json";
import kochi from "../data/climate/kochi.json";

/** One climate object per city. Each is generated by scripts/fetch-climate.mjs. */
export const CLIMATES = { delhi, jaipur, ahmedabad, kochi };

export const SITE_IDS = Object.keys(CLIMATES);
export const DEFAULT_SITE = "delhi";

/** The climate for a city id. Unknown ids fall back to Delhi. */
export function climateFor(siteId) {
  return CLIMATES[siteId] ?? CLIMATES[DEFAULT_SITE];
}
